// Helper Query Functions
export function getDistricts(): District[] {
  return GUJARAT_LOCATION_MASTER;
}

export function getDistrictById(districtId: string): District | undefined {
  return GUJARAT_LOCATION_MASTER.find(
    d => d.id === districtId || d.name.toLowerCase() === districtId.toLowerCase()
  );
}

export function getTalukasByDistrict(districtId: string): Taluka[] {
  const district = getDistrictById(districtId);
  return district ? district.talukas : [];
}

export function getTalukaById(talukaId: string): Taluka | undefined {
  for (const d of GUJARAT_LOCATION_MASTER) {
    const t = d.talukas.find(
      tal => tal.id === talukaId || tal.name.toLowerCase() === talukaId.toLowerCase()
    );
    if (t) return t;
  }
  return undefined;
}

export function getVillagesByTaluka(talukaId: string): Village[] {
  const taluka = getTalukaById(talukaId);
  return taluka ? taluka.villages : [];
}

export function getVillageById(villageId: string): Village | undefined {
  for (const d of GUJARAT_LOCATION_MASTER) {
    for (const t of d.talukas) {
      const v = t.villages.find(
        vil => vil.id === villageId || vil.name.toLowerCase() === villageId.toLowerCase()
      );
      if (v) return v;
    }
  }
  return undefined;
}
